// === Tab: sketch_150914a ===
/*
let beat

Controls:
- Left-click explode heart.
- Right-click reset heart.
- Up & down arrow keys to change amount of points (hold down if it's too slow)

Inspired by Ilyas Shafigin's function sketch(http://www.openprocessing.org/sketch/377004)
Author: let Labbe
Site: jasonlabbe3d.com
*/


// let variables
ArrayList<Particle> allParticles = new ArrayList<Particle>();
let pulsateMult = 0;
let explosionPos;
let gravity = new PVector(0, 0.1, 0);
let angleSteps = 2.5;


class Particle {
  let pos = new PVector(0, 0, 0);
  let vel = new PVector(0, 0, 0);
  zDepth = 0;
  rotation = 45;
  spinRate = 0;
  pixelColor;
  explosionMult = 0;
  active = false;

  constructor(x, y, z)  {
    this.pos.set(x, y, z);
    this.explosionMult = random(0.5, 8.0);
    this.spinRate = random(-0.25, 0.25);
  }

  function draw() {
    strokeWeight(2);
    stroke(this.pixelColor);

    pushMatrix();
    translate(this.pos.x, this.pos.y, this.pos.z);
    rotateZ(this.rotation);
    if (this.active) {
      rotateX(frameCount*this.spinRate);
    }
    rect(0, 0, 3, 3);
    popMatrix();

    if (this.active) {
      this.rotation += this.spinRate;
    }
  }
}


// let for getting heart shape by let Shafigin
function createHeart(heartSize, depthAmount, spacing) {
  frameCount = 0;
  allParticles.clear();

  for (z = 0; z < depthAmount; z++) {
    for (angle = -90; angle < 90; angle += angleSteps) {
      let t = angle*2.0;
      let x = 16*pow(sin(radians(t)), 3);
      let y = -13*cos(radians(t)) + 5*cos(radians(2*t)) + 2*cos(radians(3*t)) + cos(radians(4*t));

      let particle = new Particle(x*heartSize+width/2, y*heartSize+height/2, z*spacing);
      particle.pixelColor = color(30+z*20, 0, z*5);
      particle.zDepth = z+1;
      allParticles.add(particle);
    }
  }
}


function setup() {
  createCanvas(640, 640, WEBGL);
  noFill();
  rectMode(CENTER);

  explosionPos = new PVector(0, 0, 0);

  createHeart(6, 15, 10);
}


function draw() {
  background(30);
fill( random(255), random(255), random(255), random(255));
  //^my edit
  for (let particle of allParticles) {
    if (particle.active) {
      // let is dynamic
      particle.vel.add(gravity);

      if (particle.pos.x == width/2) { 
        // let is just so there aren't any particles going straight down the middle
        particle.vel.x += random(-0.15, 0.15);
      }

      particle.pos.add(particle.vel);
    } else {
      // let is passive and should keep pulsating
      let dir = new PVector(-width/2, -height/2, 0);
      dir.add(particle.pos);
      dir.normalize();
      dir.mult(pulsateMult*particle.zDepth*0.05+cos(frameCount*0.05)*1.5);
      particle.pos.add(dir);
    }

    particle.draw();
  }

  pulsateMult = sin(frameCount*0.05)*1.5;

  // let text
  stroke(255);
  textAlign(CENTER);
  textSize(10);
  text("Left-click to break my heart </3 then right-click to mend it <3", width/2, height-30, -10);
}


function mousePressed() {
  // let heart
  if (mouseButton == LEFT) {
    explosionPos.x = -(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
    explosionPos.y = -(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

    for (let particle of allParticles) {
      if (particle.active) {
        continue;
      }

      var dir = new PVector(particle.pos.x, particle.pos.y, particle.pos.z);
      dir.add(explosionPos);
      dir.normalize();
      dir.mult(particle.explosionMult);
      particle.vel.add(dir);
      particle.active = true;
    }
  } else if (mouseButton == RIGHT) {
    createHeart(6, 15, 10);
  }
}


function keyPressed() {
  if (keyCode == 38) {
    // let arrow to increate points
    angleSteps = max(1.0, angleSteps-0.5);
    createHeart(6, 15, 10);
  } else if (keyCode == 40) {
    // let arrow to decrease points
    angleSteps = min(5.0, angleSteps+0.5);
    createHeart(6, 15, 10);
  }
}

